// src/components/AdminManageFee.jsx
import React, { useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminManageFee() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  // Class-based base keys
  const getBaseKeysForClass = (cls) => {
    const c = Number(cls);
    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];
    return ["exam", "tuition", "development"];
  };

  // Fetch student + fees
  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Enter admission number");
    setLoading(true);
    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${encodeURIComponent(admissionNo)}`
      );

      if (!res.data.success) {
        setData(null);
        toast.error(res.data.error || "Record not found");
        return;
      }

      const incoming = res.data.data;

      // Class-based fees
      const fs = res.data.feeStructure || {};
      const baseItemsArray = fs.items || [];
      const baseItems = {};
      baseItemsArray.forEach((item) => {
        baseItems[item.key] = { title: item.title, amount: item.amount };
      });

      // Student-specific fees
      const studentItems = {};
      const overrides = incoming.student.feeOverrides || {};
      if (overrides) {
        Object.keys(overrides).forEach((k) => {
          studentItems[k] = {
            title: overrides[k].title || k,
            amount: overrides[k].amount || overrides[k],
          };
        });
      }

      setData({
        student: incoming.student,
        baseItems,
        studentItems,
      });

      toast.success("Student record loaded");
    } catch (err) {
      console.error(err);
      toast.error("Failed to load");
    } finally {
      setLoading(false);
    }
  };

  // Add student-specific fee
  const addFeeItem = async () => {
    if (!data?.student) return toast.error("Load a student first");

    const { value: form } = await Swal.fire({
      title: "Add Fee Type for this student",
      html: `
        <input id="key" class="swal2-input" placeholder="Key (e.g., sports)" />
        <input id="title" class="swal2-input" placeholder="Title (e.g., Sports Fee)" />
        <input id="amount" type="number" class="swal2-input" placeholder="Amount" />
      `,
      preConfirm: () => ({
        key: document.getElementById("key").value.trim(),
        title: document.getElementById("title").value.trim(),
        amount: Number(document.getElementById("amount").value),
      }),
      showCancelButton: true,
      confirmButtonText: "Add",
    });

    if (!form) return;
    if (!form.key || !form.title || !form.amount)
      return toast.error("All fields required");

    try {
      const res = await axios.post(
        "http://localhost:5000/api/fees/admin/addItem",
        {
          admissionNo: data.student.admissionNo,
          ...form,
        }
      );

      if (res.data.success) {
        toast.success("Added for student");

        // Update local state immediately
        setData((prev) => ({
          ...prev,
          studentItems: {
            ...prev.studentItems,
            [form.key]: { title: form.title, amount: form.amount },
          },
        }));
      } else toast.error(res.data.error || "Failed to add");
    } catch (err) {
      console.error(err);
      toast.error("Failed to add");
    }
  };

  // Edit student-specific fee
  const editFeeItem = async (key) => {
    if (!data?.student) return toast.error("Load a student first");

    const item = data.studentItems[key];
    if (!item) return;

    const { value: form } = await Swal.fire({
      title: `Edit ${key}`,
      html: `
        <input id="title" class="swal2-input" value="${item.title}" />
        <input id="amount" type="number" class="swal2-input" value="${item.amount}" />
      `,
      preConfirm: () => ({
        title: document.getElementById("title").value.trim(),
        amount: Number(document.getElementById("amount").value),
      }),
      showCancelButton: true,
      confirmButtonText: "Update",
    });

    if (!form) return;

    try {
      const res = await axios.put(
        "http://localhost:5000/api/fees/admin/updateItem",
        {
          admissionNo: data.student.admissionNo,
          key,
          ...form,
        }
      );

      if (res.data.success) {
        toast.success("Updated");

        setData((prev) => ({
          ...prev,
          studentItems: {
            ...prev.studentItems,
            [key]: { title: form.title, amount: form.amount },
          },
        }));
      } else toast.error(res.data.error || "Failed to update");
    } catch (err) {
      console.error(err);
      toast.error("Update failed");
    }
  };

  // Delete student-specific fee
  const deleteFeeItem = async (key) => {
    if (!data?.student) return toast.error("Load a student first");

    const ok = await Swal.fire({
      title: "Delete?",
      text: `Remove "${key}" fee for this student?`,
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Delete",
    });

    if (!ok.isConfirmed) return;

    try {
      const res = await axios.delete(
        "http://localhost:5000/api/fees/admin/deleteItem",
        {
          data: { admissionNo: data.student.admissionNo, key },
        }
      );

      if (res.data.success) {
        toast.success("Deleted");

        setData((prev) => {
          const updated = { ...prev.studentItems };
          delete updated[key];
          return { ...prev, studentItems: updated };
        });
      } else toast.error(res.data.error || "Delete failed");
    } catch (err) {
      console.error(err);
      toast.error("Delete failed");
    }
  };

  const renderFeeTable = () => {
    if (!data) return null;
    const { student, baseItems, studentItems } = data;

    return (
      <div className="fee-card">
        <h3>
          Manage Fee — {student.studentName} (Class {student.classApplied})
        </h3>

        <div style={{ marginBottom: 12 }}>
          <button className="primary-btn" onClick={addFeeItem}>
            + Add Fee Type for this student
          </button>
        </div>

        {/* Class-based fees */}
        <h4>Class-based Fees</h4>
        <table className="fee-table">
          <thead>
            <tr>
              <th>Key</th>
              <th>Title</th>
              <th>Amount</th>
            </tr>
          </thead>
          <tbody>
            {Object.keys(baseItems || {}).map((k) => (
              <tr key={k}>
                <td>{k}</td>
                <td>{baseItems[k].title}</td>
                <td>₹{(baseItems[k].amount || 0).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Student-specific fees */}
        {Object.keys(studentItems || {}).length > 0 && (
          <>
            <h4>Student-specific Fees</h4>
            <table className="fee-table">
              <thead>
                <tr>
                  <th>Key</th>
                  <th>Title</th>
                  <th>Amount</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {Object.keys(studentItems).map((k) => (
                  <tr key={k}>
                    <td>{k}</td>
                    <td>{studentItems[k].title}</td>
                    <td>₹{(studentItems[k].amount || 0).toLocaleString()}</td>
                    <td>
                      <button
                        className="secondary-btn"
                        onClick={() => editFeeItem(k)}
                      >
                        Edit
                      </button>
                      <button
                        className="danger-btn"
                        onClick={() => deleteFeeItem(k)}
                        style={{ marginLeft: 8 }}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}
      </div>
    );
  };

  return (
    <div className="fee-page">
      <Toaster />
      <div className="fee-container">
        <h2>Manage Student Fee Structure</h2>

        <div className="search-box" style={{ marginBottom: 12 }}>
          <input
            type="text"
            placeholder="Enter Admission No."
            value={admissionNo}
            onChange={(e) => setAdmissionNo(e.target.value)}
          />
          <button onClick={fetchFee} disabled={loading}>
            {loading ? "Loading..." : "Search"}
          </button>
        </div>

        {renderFeeTable()}
      </div>
    </div>
  );
}
